INSERT INTO posts (slug, title, date, category, "readTime", excerpt, content, created_at) VALUES (
  'busy-ness-and-leverage',
  'Busy-ness and Leverage',
  '5 Jun 2026',
  'Leadership Architecture',
  6,
  'Most of us settle for a pattern of leverage we''re used to — a day filled with tasks we think we''re good at. The make or buy choice is one we face all day, every day, and rarely consider with the rigour it deserves.',
  $json$[
    {"type":"p","text":"When I made breakfast this morning, I didn't begin by making the blender. Someone else, a team with more skills, resources and scale, built the blender. I simply bought it."},
    {"type":"p","text":"That seems obvious — no one expects a from-scratch baker to make their own baking powder."},
    {"type":"p","text":"And yet, our projects are rarely fine-tuned around leverage."},
    {"type":"h2","text":"What Are You Hiring Yourself to Do?"},
    {"type":"p","text":"Are you making that choice because your labour is cheap and convenient, or because it's the place of maximum leverage? It's often easier to be busy than it is to be productive."},
    {"type":"p","text":"Busy is a morally superior distraction. Busy gets us off the hook. Busy is a great place to hide."},
    {"type":"p","text":"On the other hand, productive can be scary. When you're buying someone else's skill and time, you're making a different sort of commitment."},
    {"type":"p","text":"Your job might not be to do your job. Your job might be to make the decisions and commitments needed to lead other people who do your (former) job."},
    {"type":"h2","text":"The Make or Buy Calculation"},
    {"type":"p","text":"The calculation is simple: if the commercial project is worth doing, what's the most direct, cheapest and fastest way to get it done well?"},
    {"type":"p","text":"There's nothing wrong with hiring yourself to do things you enjoy. And it's imperative that when you embrace leverage to get projects done, you produce work you're proud of — shipping junk, at scale, is not the point."},
    {"type":"p","text":"But my guess is that most of us settle for a pattern of leverage that we're used to, a pace that we've become accustomed to, a day filled with tasks we think we're good at. I've talked to people all over the world — entrepreneurs, freelancers, employees and bosses — and most of them are sure that they're leveraging just the right amount. Even though it's different for everyone."},
    {"type":"p","text":"The make or buy choice is one we face all day, every day, and rarely consider."},
    {"type":"p","text":"If you're serious about the project, it's time to give yourself a promotion, and to hire yourself to do work that's yours and yours alone to contribute. It's almost certain that there's someone cheaper, faster and yes, better at the other work than you are."},
    {"type":"quote","text":"On our best days, what we actually make is decisions."},
    {"type":"p","text":"You might need to invest some time and energy to get the skills you need to find this leverage. To be smart about the tools you use and the people you hire. That's an investment worth making."},
    {"type":"p","text":"Find the resources you need, and figure out how to work with them. Then hire someone else to make a blender."}
  ]$json$::jsonb,
  NOW()
) ON CONFLICT (slug) DO NOTHING;
